use mspaint_port::geometry::mul_div;

#[test]
fn matches_recorded_windows_muldiv_results() {
    // Independently captured from kernel32.dll on Windows, not generated by
    // the Rust implementation. The fixture keeps this check portable.
    let fixture = include_str!("fixtures/windows_muldiv.csv");
    let mut cases = 0;
    for line in fixture.lines().skip(1) {
        let values: Vec<i32> = line
            .split(',')
            .map(|value| value.parse().unwrap())
            .collect();
        assert_eq!(values.len(), 4);
        assert_eq!(
            mul_div(values[0], values[1], values[2]),
            values[3],
            "{line}"
        );
        cases += 1;
    }
    assert_eq!(cases, 729);
}
